{"content":"def fizzbuzz(n):
    """Return FizzBuzz strings for integers from 1 through n."""
    return [
        "FizzBuzz" if number % 15 == 0 else
        "Fizz" if number % 3 == 0 else
        "Buzz" if number % 5 == 0 else
        str(number)
        for number in range(1, n + 1)
    ]
