{"content":"import unittest

from fizzbuzz import fizzbuzz


class FizzBuzzTests(unittest.TestCase):
    def test_first_fifteen_values(self):
        self.assertEqual(
            fizzbuzz(15),
            [
                "1", "2", "Fizz", "4", "Buzz",
                "Fizz", "7", "8", "Fizz", "Buzz",
                "11", "Fizz", "13", "14", "FizzBuzz",
            ],
        )

    def test_single_value(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_nonpositive_limits_return_empty_lists(self):
        for n in (0, -1, -15):
            with self.subTest(n=n):
                self.assertEqual(fizzbuzz(n), [])

    def test_multiple_cycles_and_inclusive_endpoint(self):
        result = fizzbuzz(31)
        self.assertEqual(len(result), 31)
        for number, value in enumerate(result, start=1):
            with self.subTest(number=number):
                expected = ""
                if number % 3 == 0:
                    expected += "Fizz"
                if number % 5 == 0:
                    expected += "Buzz"
                self.assertEqual(value, expected or str(number))
                self.assertIsInstance(value, str)


if __name__ == "__main__":
    unittest.main()
